package br.com.equilibra.recurrence.domain;
import jakarta.persistence.*;import java.math.*;import java.time.*;import java.util.UUID;
@Entity @Table(name="recurrence_rules") public class RecurrenceRule { @Id @Column(length=36,updatable=false) private String id;@Column(name="owner_id",nullable=false,updatable=false)private String ownerId;@Enumerated(EnumType.STRING)@Column(nullable=false)private RecurrenceType type;@Column(nullable=false,length=255)private String description;@Column(nullable=false,precision=19,scale=2)private BigDecimal amount;@Column(name="category_id",nullable=false)private String categoryId;@Column(name="account_id",nullable=false)private String accountId;@Enumerated(EnumType.STRING)@Column(nullable=false)private RecurrenceFrequency frequency;@Column(name="start_date",nullable=false)private LocalDate startDate;@Column(name="end_date")private LocalDate endDate;@Column(name="due_day",nullable=false)private int dueDay;@Enumerated(EnumType.STRING)@Column(nullable=false)private RecurrenceStatus status=RecurrenceStatus.ACTIVE;@Column(name="created_at",nullable=false,updatable=false)private Instant createdAt;@Column(name="updated_at",nullable=false)private Instant updatedAt;@Version private Long version;protected RecurrenceRule(){}public RecurrenceRule(String owner,RecurrenceType type,String description,BigDecimal amount,String category,String account,RecurrenceFrequency frequency,LocalDate start,LocalDate end,int day){id=UUID.randomUUID().toString();ownerId=owner;this.type=type;rename(description);changeAmount(amount);categoryId=category;accountId=account;this.frequency=frequency;startDate=start;endDate=end;dueDay=day;if(start==null||end!=null&&end.isBefore(start)||day<1||day>31)throw new IllegalArgumentException("invalid recurrence dates");}public void rename(String v){if(v==null||v.isBlank()||v.trim().length()>255)throw new IllegalArgumentException("description is invalid");description=v.trim();}public void changeAmount(BigDecimal v){if(v==null||v.signum()<=0||v.scale()>2)throw new IllegalArgumentException("amount is invalid");amount=v.setScale(2);}public void pause(){if(status!=RecurrenceStatus.ACTIVE)throw new IllegalStateException("invalid transition");status=RecurrenceStatus.PAUSED;}public void resume(){if(status!=RecurrenceStatus.PAUSED)throw new IllegalStateException("invalid transition");status=RecurrenceStatus.ACTIVE;}public void end(){if(status==RecurrenceStatus.CANCELLED)throw new IllegalStateException("invalid transition");status=RecurrenceStatus.ENDED;}public void cancel(){if(status==RecurrenceStatus.ENDED)throw new IllegalStateException("invalid transition");status=RecurrenceStatus.CANCELLED;}@PrePersist void create(){Instant n=Instant.now();createdAt=n;updatedAt=n;}@PreUpdate void update(){updatedAt=Instant.now();}public String getId(){return id;}public String getOwnerId(){return ownerId;}public RecurrenceType getType(){return type;}public String getDescription(){return description;}public BigDecimal getAmount(){return amount;}public String getCategoryId(){return categoryId;}public String getAccountId(){return accountId;}public RecurrenceFrequency getFrequency(){return frequency;}public LocalDate getStartDate(){return startDate;}public LocalDate getEndDate(){return endDate;}public int getDueDay(){return dueDay;}public RecurrenceStatus getStatus(){return status;}public Instant getCreatedAt(){return createdAt;}public Instant getUpdatedAt(){return updatedAt;}}
